import 'fake-indexeddb/auto';
import {it,expect,afterEach} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {nativeDocuments} from '../src/sync/nativeBridge';
import {ScopedEditorStore,type EditorImage} from '../src/sync/editorStore';
import {ContractSyncServer} from '../src/sync/testing';
import {createSyncOperation,valueHash,type SyncSession,type SyncDocument} from '../src/sync/protocol';
const root='/tmp/shinariokanri-independent-rb09-73a279a/independent',stores:ScopedEditorStore[]=[];
afterEach(async()=>{for(const s of stores.splice(0))await s.delete();});
function proof(id:string,value:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(value,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string},account=newId(),owner=newId(),docs=nativeDocuments(f.p,'1').filter(d=>d.fields.kind==='note').map(d=>({...d,fields:Object.fromEntries(Object.entries(d.fields).filter(([k])=>['name','kind','visibility','createdAt'].includes(k)))})),image:EditorImage={authorizationRevision:'1',authorizationExpiresAt:null,projectId:f.p.projectId,serverRevision:'1',documents:docs,contentHash:await valueHash(docs)},store=new ScopedEditorStore(account),session:SyncSession={accountId:account,authenticated:true,generation:newId()},server=new ContractSyncServer();stores.push(store);await store.receive(image);server.seed({projectId:f.p.projectId,revision:'1',documents:docs,members:{[account]:'editor',[owner]:'owner'}});return {...f,account,owner,image,store,server,session};}
async function authorizedSend(server:ContractSyncServer,op:Parameters<ContractSyncServer['send']>[0],session:SyncSession){return {...await server.send(op,session),authorizationRevision:'1',authorizationExpiresAt:null};}
function reopen(s:ScopedEditorStore){(s as unknown as {db:{close():void}}).db.close();const next=new ScopedEditorStore(s.accountId);stores.push(next);return next;}
it('R9EV01 limited editor ordinary save→prepare→ACK→cold reopen retains its approved fields and no project/private canonical records',async()=>{const f=await seed();await f.store.saveField(f.p.projectId,f.idA,'name','許可された改名😀');const op=(await f.store.prepare(f.p.projectId))!,ack=await authorizedSend(f.server,op,f.session);await f.store.acknowledge(ack);f.store=reopen(f.store);const work=(await f.store.get(f.p.projectId))!;expect(work.base.serverRevision).toBe('2');expect(work.documents.find(d=>d.id===f.idA)?.fields.name).toBe('許可された改名😀');expect(work.prepared).toBeUndefined();expect(work.acks).toHaveLength(1);expect(work.documents.every(d=>d.fields.kind==='note'&&Object.keys(d.fields).every(k=>['name','kind','visibility','createdAt'].includes(k)))).toBe(true);proof('R9EV01',work);});
it('R9EV02 post-ACK conflict outside the original sent target preserves later local choice across cold reopen and explicit full resolution',async()=>{const f=await seed();await f.store.saveField(f.p.projectId,f.idA,'name','先に送るA');const op=(await f.store.prepare(f.p.projectId))!,b=f.image.documents.find(d=>d.id===f.idB)!,remote=structuredClone(b);remote.fields.name='遠隔で変えたB';const outside=await createSyncOperation({operationId:newId(),scope:{accountId:f.owner,projectId:f.p.projectId},baseRevision:'1',targets:[{base:b,local:remote}]});await authorizedSend(f.server,outside,{accountId:f.owner,authenticated:true,generation:newId()});const ack=await authorizedSend(f.server,op,f.session);await f.store.saveField(f.p.projectId,f.idB,'name','送信中に書いたB');await f.store.acknowledge(ack);f.store=reopen(f.store);const captured=(await f.store.get(f.p.projectId))!;expect(captured.postConflicts?.map(c=>c.targetId)).toEqual([f.idB]);expect(captured.documents.find(d=>d.id===f.idB)?.fields.name).toBe('送信中に書いたB');expect(captured.prepared?.operation.operationId).toBe(op.operationId);await f.store.resolve(f.p.projectId,{[f.idB]:{strategy:'local'}},captured.revision);const resolved=(await f.store.prepare(f.p.projectId))!;expect(resolved.targets.map(t=>t.targetId)).toEqual(expect.arrayContaining([f.idA,f.idB]));const result=await authorizedSend(f.server,resolved,f.session);await f.store.acknowledge(result);const final=(await f.store.get(f.p.projectId))!;expect(final.documents.find(d=>d.id===f.idB)?.fields.name).toBe('送信中に書いたB');expect(final.conflict).toBeUndefined();expect(final.prepared).toBeUndefined();proof('R9EV02',{originalOp:op,ack,captured,resolved,final});});
it('R9E01 concurrent identical limited-editor ACKs both succeed without duplicate history/evidence',async()=>{const f=await seed();await f.store.saveField(f.p.projectId,f.idA,'name','同時ACKの限定編集');const op=(await f.store.prepare(f.p.projectId))!,ack=await authorizedSend(f.server,op,f.session),results=await Promise.allSettled([f.store.acknowledge(ack),f.store.acknowledge(ack)]),after=await f.store.get(f.p.projectId);proof('R9E01',{results:results.map(x=>x.status==='fulfilled'?{status:x.status}:{status:x.status,message:String(x.reason),code:x.reason?.code}),after});expect(results.every(x=>x.status==='fulfilled')).toBe(true);expect(after?.acks).toHaveLength(1);expect(after?.prepared).toBeUndefined();});
it('R9E02 a stale incoming limited-editor image cannot roll the confirmed server edition and content back after a successful ACK',async()=>{const f=await seed();await f.store.saveField(f.p.projectId,f.idA,'name','確定した新しい本文名');const op=(await f.store.prepare(f.p.projectId))!;await f.store.acknowledge(await authorizedSend(f.server,op,f.session));const before=await f.store.get(f.p.projectId);let code='';try{await f.store.receive(f.image);}catch(cause){code=(cause as {code?:string}).code??String(cause);}const after=await f.store.get(f.p.projectId);proof('R9E02',{initialImage:f.image,before,after,code});expect(code).toBe('REVISION_CHANGED');expect(after).toEqual(before);});

it('R9E00 ordinary editor field save never mutates the confirmed base and prepares a nonempty operation',async()=>{const f=await seed(),initial=await f.store.get(f.p.projectId);await f.store.saveField(f.p.projectId,f.idA,'name','送信する通常入力');const after=await f.store.get(f.p.projectId),operation=await f.store.prepare(f.p.projectId);proof('R9E00',{initial,after,operation,baseLocalShareReference:after?.base.documents[0]===after?.documents[0],baseHashStillValid:await valueHash(after!.base.documents)===after!.base.contentHash});expect(after?.base).toEqual(f.image);expect(operation).not.toBe(null);expect(operation?.targets.find(t=>t.targetId===f.idA)?.local.fields.name).toBe('送信する通常入力');});
